llm.raw_content:
{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C08", "C160", "C185", "C205"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C08", "C160", "C185", "C205"],
  "claims": [
    {
      "claim": "Neostigmine, a close quaternary ammonium carbamate analog, showed only 12.8% absorption from rat jejunum over 2 h and 6.6% of the dose trapped in the gut wall after 3 h, indicating substantial presystemic loss for this chemotype.",
      "card_ids": ["C160", "C185"]
    },
    {
      "claim": "Neostigmine is a P-gp substrate with an efflux ratio of 2.2 in MDR1-MDCKII monolayers, adding gut-wall efflux as a mechanism limiting systemic entry.",
      "card_ids": ["C205"]
    },
    {
      "claim": "Physostigmine, another carbamate acetylcholinesterase inhibitor, is reported to have poor oral bioavailability, supporting a low F for the carbamate class.",
      "card_ids": ["C08"]
    },
    {
      "claim": "L6 rivastigmine records show that carbamate hepatic clearance can be moderate (observed CLint 14.1 mL/min/kg; hepatocyte CLint 8.43 mL/min/kg) but CYP plays a minimal role; without direct pyridostigmine hepatic data, L6 does not change the absorption-limited low-F conclusion.",
      "card_ids": ["C239", "C241", "C224"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C224", "C239", "C241"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for pyridostigmine in any supplied record.",
    "No matched oral versus IV exposure data for pyridostigmine.",
    "Neostigmine absorption data are from rat jejunum single-loop preparations, not whole-intestinal or human F.",
    "L6 hepatic-clearance records are for other molecules (rivastigmine, phenacetin, agomelatine, carbamate insecticides) and do not directly measure pyridostigmine metabolism.",
    "Exact salt form and counterion are not specified.",
    "Property tool reports neutral fraction 1 despite the formal quaternary charge, adding uncertainty."
  ],
  "decision_summary": "Prediction remains low. L6 hepatic-clearance records are mostly for unrelated molecules and do not directly measure pyridostigmine; the absorption-limited presystemic-loss evidence from neostigmine (12.8% jejunal absorption, gut-wall trapping, P-gp efflux) and physostigmine's poor oral bioavailability still supports F < 20%."
}

